// This file is generated by AI.

// Tauri 命令封装（视频导出）。

import { invoke } from '@tauri-apps/api/core';

export interface VideoExportResult {
  output: string;
  /** 实际使用的编码后端；音频导出或未回调时为 null。 */
  encoder?: string | null;
}

export interface VideoExportStatus {
  /** 当前构建是否链接了渲染器（Windows + video-export 特性）。 */
  supported: boolean;
  /** 是否已导入 Live2DCubismCore.dll。 */
  live2dCore: boolean;
  live2dPath: string | null;
}

export interface VideoProjectInfo {
  scenes: string[];
  startScene: string;
  /** 舞台宽度（game/config.txt 的 Stage_Width）。 */
  stageWidth: number;
  /** 舞台高度（game/config.txt 的 Stage_Height）。 */
  stageHeight: number;
  /** webgal-engine.json 声明的 WebGAL 版本；用于自动选择立绘切换口径。 */
  webgalVersion: string | null;
}

export interface RouteNode {
  kind: string;
  scene: string;
  line: number;
  target: string | null;
  options: string[];
  selected: number | null;
  blocked: boolean;
}

export interface RoutePreview {
  nodes: RouteNode[];
  complete: boolean;
  stopReason: string | null;
}

export interface VideoExportOptions {
  /** 分辨率预设高度（720 / 1080 / 1440 / 2160）；宽度由舞台宽高比推导。 */
  resolution?: number;
  fps?: number;
  bitrateKbps?: number;
  encoder?: string;
  includeAudio?: boolean;
  uiOnly?: boolean;
  stageOnly?: boolean;
  selected?: Record<string, number>;
  fontScale?: number;
  textSpeed?: number;
  autoSpeed?: number;
  /** 立绘身份判定：auto / legacy（4.6.3 及以前）/ modern（4.6.4+）。 */
  figureSide?: string;
  disableFilters?: boolean;
  audioOnly?: boolean;
}

export function videoProjectInfo(projectPath: string): Promise<VideoProjectInfo> {
  return invoke<VideoProjectInfo>('video_project_info', { projectPath });
}

export function exportVideo(
  projectPath: string,
  outputPath: string,
  startScene?: string,
  options?: VideoExportOptions
): Promise<VideoExportResult> {
  return invoke<VideoExportResult>('export_video', {
    projectPath,
    outputPath,
    startScene: startScene && startScene.length > 0 ? startScene : null,
    options: options ?? null,
  });
}

export function videoRoutePreview(
  projectPath: string,
  startScene: string,
  selected: Record<string, number>
): Promise<RoutePreview> {
  return invoke<RoutePreview>('video_route_preview', {
    projectPath,
    startScene,
    selected,
  });
}

export function videoExportStatus(): Promise<VideoExportStatus> {
  return invoke<VideoExportStatus>('video_export_status');
}

export function importCubismCore(source: string): Promise<VideoExportStatus> {
  return invoke<VideoExportStatus>('import_cubism_core', { source });
}

/** 取消正在运行的导出；没有任务时返回 false。 */
export function cancelVideoExport(): Promise<boolean> {
  return invoke<boolean>('cancel_video_export');
}

/** 渲染器每秒推一次进度（`video-export:progress` 事件）。 */
export interface VideoExportProgress {
  phase: string;
  current: number;
  total: number;
  fps: number;
}

/** 渲染器约每秒推一帧预览（`video-export:preview` 事件），`data` 是 PNG data URL。 */
export interface VideoExportPreview {
  frame: number;
  total: number;
  data: string;
}
